.bcn-review {
  gap: var(--spacing-400);
  flex-direction: column;
  display: flex;
}
.bcn-review__head {
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-300);
  flex-wrap: wrap;
  display: flex;
}
.bcn-review__title {
  align-items: center;
  gap: var(--spacing-200);
  font-size: var(--font-size-300);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
  display: flex;
}
.bcn-review__title .esa-icon {
  color: var(--color-background-utility-warning);
  flex-shrink: 0;
}
.bcn-review__counts {
  align-items: center;
  gap: var(--spacing-300);
  font-size: var(--font-size-100);
  display: inline-flex;
