.bcn-review__section:hover {
  background: color-mix(in srgb, var(--color-commitment) 20%, white);
}
.bcn-review__groups {
  gap: var(--spacing-500);
  flex-direction: column;
  display: flex;
}
.bcn-review__group {
  gap: var(--spacing-300);
  flex-direction: column;
  display: flex;
}
.bcn-review__field {
  align-items: center;
  gap: var(--spacing-150);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--color-content-default-tertiary);
  margin: 0;
  display: flex;
}
.bcn-review__field .esa-icon {
  color: var(--bcn-content-muted);
}
.bcn-review__list,
.bcn-review__replies {
  margin: 0;
  padding: 0;
  list-style: none;
}
.bcn-review__item {
  gap: var(--spacing-300);
  padding: var(--spacing-300);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  background: var(--color-background-elevation-raised);
  grid-template-columns: auto 1fr;
  display: grid;
}
.bcn-review__item + .bcn-review__item {
  margin-top: var(--spacing-200);
}
.bcn-review__body {
  gap: var(--spacing-150);
  flex-direction: column;
  min-width: 0;
  display: flex;
}
.bcn-review__meta {
  align-items: center;
  gap: var(--spacing-200);
  flex-wrap: wrap;
  display: flex;
}
.bcn-review__author {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.bcn-review__time {
  color: var(--color-content-default-tertiary);
  font-size: 0.75rem;
}
.bcn-review__tags {
  align-items: center;
  gap: var(--spacing-150);
  flex-wrap: wrap;
  margin-left: auto;
  display: inline-flex;
}
.bcn-review__text {
  font-size: var(--font-size-200);
  color: var(--color-content-default-secondary);
  margin: 0;
  line-height: 1.55;
}
.bcn-review__replies {
  margin-top: var(--spacing-200);
  padding-left: var(--spacing-400);
  border-left: 2px solid var(--color-border-default);
  gap: var(--spacing-200);
  flex-direction: column;
  display: flex;
}
.bcn-review__reply {
  gap: var(--spacing-200);
  grid-template-columns: auto 1fr;
  display: grid;
}
.bcn-review__node--reply .esa-avatar {
  --_avatar-bg: var(--color-background-brand-muted);
}
.esa-badge {
  --_badge-bg: var(--badge-bg, var(--color-background-elevation-raised, #fcfcfc));
  --_badge-text: var(--badge-text-color, var(--color-content-default-secondary, #646464));
  --_badge-border: var(--badge-border-color, var(--color-border-default, #cecece));
  --_badge-padding-y: var(--spacing-150, 0.375rem);
  --_badge-padding-x: var(--spacing-200, 0.5rem);
  min-width: calc(1lh + 2 * var(--_badge-padding-y));
  padding-block: var(--_badge-padding-y);
  padding-inline: var(--_badge-padding-x);
  border-radius: var(--radius-chip, var(--radius-sm, 0.25rem));
  background: var(--_badge-bg);
  color: var(--_badge-text);
  white-space: nowrap;
  box-sizing: border-box;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.esa-badge--sm {
  --_badge-padding-y: var(--spacing-100, 0.25rem);
  --_badge-padding-x: var(--spacing-150, 0.375rem);
}
.esa-badge--secondary {
  --_badge-bg: var(--color-background-brand-muted, #e9f6e9);
  --_badge-text: var(--color-content-on-brand-muted, #203c25);
}
.esa-badge--warning {
  --_badge-bg: var(--color-background-utility-warning-muted, #fff7c2);
  --_badge-text: var(--color-content-utility-warning, #ab6400);
  --_badge-border: var(--color-border-utility-warning, #f3d673);
}
.esa-badge--neutral:not(.esa-badge--dot),
.esa-badge--success:not(.esa-badge--dot),
.esa-badge--warning:not(.esa-badge--dot),
.esa-badge--danger:not(.esa-badge--dot),
.esa-badge--info:not(.esa-badge--dot) {
  border: 1px solid var(--_badge-border, transparent);
}
.esa-badge--dot.esa-badge--secondary {
  --_badge-bg: var(--color-background-brand, #46a758);
}
.esa-badge--dot.esa-badge--warning {
  --_badge-bg: var(--color-background-utility-warning-hover, #ffba18);
}
